e size.", "competencyKeys": ["advanced-1", "advanced-2", "advanced-3"], "prerequisites": [], "task": {"prompt": "Defend the conclusions of your independent work. Explain the strongest evidence, address a plausible alternative and identify a limitation. Two fictional planets orbit the same star. Planet A has an average orbital distance of one unit and a period of one year; planet B has a distance of four units and a period of eight years. A diagram shows both planets drawn at the same size.", "rubric": ["Analyse unfamiliar orbital scenarios", "Connect gravity, motion and scale", "Evaluate astronomical claims using evidence"]}}}, {"depth": "advanced", "title": "Advanced check", "block_type": "quick_check", "sequence": 7, "required": true, "objective": "Transfer and justify understanding", "content": {"body": "Check your readiness to use evidence and explain a method. Two fictional planets orbit the same star. Planet A has an average orbital distance of one unit and a period of one year; planet B has a distance of four units and a period of eight years. A diagram shows both planets drawn at the same size.", "competencyKeys": [], "prerequisites": [], "quickCheck": {"prompt": "Which response best supports a defensible conclusion in this scenario?", "options": ["Explain the method, use relevant evidence and state limitations", "Give a conclusion without connecting it to evidence"], "correctIndex": 0, "explanation": "A conclusion needs an appropriate method, relevant evidence and clear limits. Your independent responses are assessed separately."}}}]}]$data$; item jsonb; block jsonb; cid uuid;
BEGIN
 FOR item IN SELECT value FROM jsonb_array_elements(pack) LOOP
  SELECT id INTO cid FROM public.concepts WHERE slug=item->>'slug';
  IF cid IS NULL THEN RAISE EXCEPTION 'Missing concept %',item->>'slug'; END IF;
  FOR block IN SELECT value FROM jsonb_array_elements(item->'blocks') LOOP
   INSERT INTO public.knowledge_blocks AS kb(concept_id,depth,block_type,title,objective,required,sequence,content,review_status)
    VALUES(cid,item->>'depth',block->>'block_type',block->>'title',block->>'objective',true,(block->>'sequence')::int,block->'content','draft')
   ON CONFLICT(concept_id,depth,sequence) DO UPDATE SET block_type=EXCLUDED.block_type,title=EXCLUDED.title,objective=EXCLUDED.objective,content=EXCLUDED.content,version=kb.version+1,updated_at=now()
    WHERE kb.review_status='draft' AND kb.content IS DISTINCT FROM EXCLUDED.content;
  END LOOP;
 END LOOP;
END;
$seed$;
COMMIT;
